/// <summary>
/// find or creates record
/// </summary>
/// <param name = "_ndxUtilitasDataRecId">NDXUtilitasData RecId</param>
/// <param name = "_value">search criteria value</param>
/// <returns>NDXUtilitasDataSearchCriteria record</returns>
static public NDXUtilitasDataSearchCriteria findOrCreateByObject(RefRecId _ndxUtilitasDataRecId, str _value)
{
    NDXUtilitasDataSearchCriteria lNDXUtilitasDataSearchCriteria;

    str value = strLRTrim(_value);

    if(_ndxUtilitasDataRecId)
    {
        lNDXUtilitasDataSearchCriteria = NDXUtilitasDataSearchCriteria::findRecId(_ndxUtilitasDataRecId, value, true);

        if(!lNDXUtilitasDataSearchCriteria && value != '')
        {
            lNDXUtilitasDataSearchCriteria.NDXUtilitasDataRefRecId = _ndxUtilitasDataRecId;
            lNDXUtilitasDataSearchCriteria.insert();
        }

        if(lNDXUtilitasDataSearchCriteria)
        {
            lNDXUtilitasDataSearchCriteria.SearchCriteria = value;

            ttsbegin;
            lNDXUtilitasDataSearchCriteria.doUpdate();
            ttscommit;
        }
    }

    return lNDXUtilitasDataSearchCriteria;
}

/// <summary>
/// find a record
/// </summary>
/// <param name = "_ndxUtilitasDataRecId">NDXUtilitasData RecId</param>
/// <param name = "_value">Search Criteria value</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>NDXUtilitasDataSearchCriteria record</returns>
static public NDXUtilitasDataSearchCriteria findRecId(RefRecId _ndxUtilitasDataRecId, str _value, boolean _forUpdate = false)
{
    NDXUtilitasDataSearchCriteria lNDXUtilitasDataSearchCriteria;

    lNDXUtilitasDataSearchCriteria.selectForUpdate(_forUpdate);

    select lNDXUtilitasDataSearchCriteria
        where lNDXUtilitasDataSearchCriteria.RecId == _ndxUtilitasDataRecId
        && lNDXUtilitasDataSearchCriteria.SearchCriteria == _value;

    return lNDXUtilitasDataSearchCriteria;
}
